<?php
require_once __DIR__ . '/../includes/auth.php';wajibAdminArea();require_once __DIR__.'/../config/database.php';
if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$pesan='';$jenis='success';$flash=$_GET['pesan']??'';$map=['tambah'=>'Keluhan berhasil dibuat.','ubah'=>'Status keluhan berhasil diperbarui.'];if(isset($map[$flash]))$pesan=$map[$flash];
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['aksi']??'')==='status'){$token=$_POST['csrf_token']??'';$id=filter_input(INPUT_POST,'id_keluhan',FILTER_VALIDATE_INT);$st=$_POST['status_penanganan']??'';if(!hash_equals($_SESSION['csrf_token'],$token)){$pesan='Permintaan tidak valid.';$jenis='danger';}elseif(!$id||!in_array($st,['menunggu','diproses','selesai'],true)){$pesan='Data status tidak valid.';$jenis='danger';}else{$q=$pdo->prepare('UPDATE keluhan SET status_penanganan=:status WHERE id_keluhan=:id');$q->execute(['status'=>$st,'id'=>$id]);header('Location: keluhan.php?pesan=ubah');exit;}}
$cari=trim($_GET['cari']??'');$status=trim($_GET['status']??'');$params=[];$sql="SELECT k.id_keluhan,k.id_penghuni,k.tanggal_keluhan,k.isi_keluhan,k.kategori_keluhan,k.status_penanganan,p.nama,r.nomor_kamar FROM keluhan k JOIN penghuni p ON p.id_penghuni=k.id_penghuni LEFT JOIN kamar r ON r.id_kamar=p.id_kamar WHERE 1=1";if($cari!==''){$sql.=' AND (p.nama LIKE :nama OR k.kategori_keluhan LIKE :kategori OR k.isi_keluhan LIKE :isi OR r.nomor_kamar LIKE :kamar)';$like="%$cari%";$params+=['nama'=>$like,'kategori'=>$like,'isi'=>$like,'kamar'=>$like];}if(in_array($status,['menunggu','diproses','selesai'],true)){$sql.=' AND k.status_penanganan=:status';$params['status']=$status;}$sql.=' ORDER BY k.tanggal_keluhan DESC,k.id_keluhan DESC';$q=$pdo->prepare($sql);$q->execute($params);$data=$q->fetchAll();$total=(int)$pdo->query('SELECT COUNT(*) FROM keluhan')->fetchColumn();$open=(int)$pdo->query("SELECT COUNT(*) FROM keluhan WHERE status_penanganan!='selesai'")->fetchColumn();$done=$total-$open;
function eKel($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function tKel($v){return $v?date('d M Y',strtotime($v)):'-';}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Keluhan | KosSpace</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="../assets/css/app.css" rel="stylesheet"></head><body><div class="app-shell d-flex"><?php include __DIR__.'/../includes/admin_sidebar.php';?><main class="app-main"><header class="topbar"><div><div class="topbar-kicker">Workspace / Operasional</div><div class="topbar-title">Penanganan keluhan penghuni</div></div><div class="user-chip"><div class="avatar"><i class="bi bi-person-fill"></i></div><div class="d-none d-sm-block"><div class="user-name"><?=eKel($_SESSION['nama']??'Pengelola')?></div><div class="user-role"><?= isPengelolaUtama() ? 'Pengelola utama' : 'Admin' ?></div></div><a href="../logout.php" class="btn btn-outline-secondary ms-1"><i class="bi bi-box-arrow-right me-1"></i><span class="d-none d-sm-inline">Keluar</span></a></div></header><section class="page-heading"><div><div class="eyebrow">Layanan penghuni</div><h1>Keluhan</h1><p>Pantau dan perbarui status penanganan keluhan penghuni.</p></div></section><?php if($pesan):?><div class="alert alert-<?=eKel($jenis)?> alert-dismissible fade show"><?=eKel($pesan)?><button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif;?><section class="row g-3 mb-4"><div class="col-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Total keluhan</span><span class="stat-icon icon-blue"><i class="bi bi-chat-square-text"></i></span></div><div class="stat-value"><?=$total?></div><div class="stat-foot">Seluruh laporan masuk</div></div></div><div class="col-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Perlu ditangani</span><span class="stat-icon icon-orange"><i class="bi bi-hourglass-split"></i></span></div><div class="stat-value"><?=$open?></div><div class="stat-foot">Menunggu atau diproses</div></div></div><div class="col-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Selesai</span><span class="stat-icon icon-green"><i class="bi bi-check-circle"></i></span></div><div class="stat-value"><?=$done?></div><div class="stat-foot">Keluhan telah selesai</div></div></div></section><section class="panel"><div class="d-flex flex-column flex-lg-row justify-content-between align-items-lg-center gap-3 mb-4"><div><h2 class="panel-title">Daftar keluhan</h2><div class="panel-subtitle">Keluhan terbaru ditampilkan paling atas.</div></div><form method="get" class="d-flex flex-column flex-sm-row gap-2"><input name="cari" class="form-control" placeholder="Cari nama, kamar, kategori..." value="<?=eKel($cari)?>"><select name="status" class="form-select"><option value="">Semua status</option><option value="menunggu" <?=$status==='menunggu'?'selected':''?>>Menunggu</option><option value="diproses" <?=$status==='diproses'?'selected':''?>>Diproses</option><option value="selesai" <?=$status==='selesai'?'selected':''?>>Selesai</option></select><button class="btn btn-outline-secondary"><i class="bi bi-search"></i> Cari</button></form></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>No.</th><th>Penghuni</th><th>Tanggal</th><th>Kategori</th><th>Keluhan</th><th>Status</th><th class="text-end">Perbarui</th></tr></thead><tbody><?php if(!$data):?><tr><td colspan="7"><div class="empty-state"><i class="bi bi-chat-square-text"></i><strong class="d-block text-dark mb-1">Belum ada keluhan</strong><span>Keluhan dari penghuni akan muncul di sini.</span></div></td></tr><?php else:foreach($data as $i=>$r):?><tr><td><?=$i+1?></td><td><strong><?=eKel($r['nama'])?></strong><div class="text-secondary small">Kamar <?=eKel($r['nomor_kamar']??'-')?></div></td><td><?=tKel($r['tanggal_keluhan'])?></td><td><?=eKel($r['kategori_keluhan'])?></td><td style="min-width:220px;max-width:360px"><?=eKel($r['isi_keluhan'])?></td><td><?php if($r['status_penanganan']==='selesai'):?><span class="soft-badge"><i class="bi bi-check-circle"></i>Selesai</span><?php elseif($r['status_penanganan']==='diproses'):?><span class="soft-badge pending"><i class="bi bi-arrow-repeat"></i>Diproses</span><?php else:?><span class="soft-badge neutral"><i class="bi bi-clock"></i>Menunggu</span><?php endif;?></td><td class="text-end"><form method="post" class="d-flex justify-content-end gap-2"><input type="hidden" name="csrf_token" value="<?=eKel($_SESSION['csrf_token'])?>"><input type="hidden" name="aksi" value="status"><input type="hidden" name="id_keluhan" value="<?=(int)$r['id_keluhan']?>"><select name="status_penanganan" class="form-select form-select-sm" style="width:125px"><option value="menunggu" <?=$r['status_penanganan']==='menunggu'?'selected':''?>>Menunggu</option><option value="diproses" <?=$r['status_penanganan']==='diproses'?'selected':''?>>Diproses</option><option value="selesai" <?=$r['status_penanganan']==='selesai'?'selected':''?>>Selesai</option></select><button class="btn btn-sm btn-primary"><i class="bi bi-check2"></i></button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section><footer class="app-footer">&copy; <?=date('Y')?> KosSpace · Sistem Informasi Pengelolaan Kos Mahasiswa</footer></main></div></body></html>